// newTestMovieComment builds a minimal, valid models.Comment for a movie
// (Comment set, no SeasonsComments), matching what
// services/comments.addCommentForMovie passes to Store.AddComment (no
// Id/CreatedAt/UpdatedAt: those are generated by the store). groupId is part
// of the comment's identity and is never empty.
func newTestMovieComment(t *testing.T, titleId, userId, groupId, text string) models.Comment {
	t.Helper()
	return models.Comment{
		TitleId: titleId,
		UserId:  userId,
		GroupId: groupId,
		Comment: &text,
	}
}

// newTestSeriesComment builds a models.Comment with the given season ->
// comment-text entries (Comment nil, SeasonsComments set), matching what
// services/comments.addCommentForTVSeries passes to Store.AddComment.
func newTestSeriesComment(t *testing.T, titleId, userId, groupId string, seasons map[string]string) models.Comment {
	t.Helper()
	now := time.Now().UTC().Truncate(time.Second)
	seasonsComments := make(models.SeasonsComments, len(seasons))
	for season, text := range seasons {
		seasonsComments[season] = models.SeasonCommentItem{
			Comment:   text,
			AddedAt:   now,
			UpdatedAt: now,
		}
	}
	return models.Comment{
		TitleId:         titleId,
		UserId:          userId,
		GroupId:         groupId,
		SeasonsComments: &seasonsComments,
	}
}

func TestStore_AddComment_GetCommentById_Movie(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupId := addTestGroup(t, s)
	titleId := "tt-movie-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	comment := newTestMovieComment(t, titleId, userId, groupId, "great movie")

	added, err := s.AddComment(ctx, comment)
	require.NoError(t, err)
	require.NotEmpty(t, added.Id, "AddComment must generate an id")
	require.Equal(t, titleId, added.TitleId)
	require.Equal(t, userId, added.UserId)
	require.Equal(t, groupId, added.GroupId, "the comment must round-trip with the group it was written in")
	require.NotNil(t, added.Comment)
	require.Equal(t, "great movie", *added.Comment)
	require.Nil(t, added.SeasonsComments, "a movie comment (no seasons) must round-trip with a nil SeasonsComments map")
	require.WithinDuration(t, time.Now(), added.CreatedAt, 5*time.Second)
	require.WithinDuration(t, time.Now(), added.UpdatedAt, 5*time.Second)

	got, err := s.GetCommentById(ctx, added.Id, userId)
	require.NoError(t, err)
	require.Equal(t, added, got)
}

func TestStore_AddComment_GetCommentById_Series(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupId := addTestGroup(t, s)
	titleId := "tt-series-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	comment := newTestSeriesComment(t, titleId, userId, groupId, map[string]string{
		"1": "season 1 was great",
		"2": "season 2 was better",
	})

	added, err := s.AddComment(ctx, comment)
	require.NoError(t, err)
	require.Equal(t, groupId, added.GroupId, "the comment must round-trip with the group it was written in")
	require.Nil(t, added.Comment, "a series comment must round-trip with a nil top-level Comment")
	require.NotNil(t, added.SeasonsComments, "a series comment with seasons must round-trip with a non-nil SeasonsComments map")
	require.Len(t, *added.SeasonsComments, 2)
	require.Equal(t, "season 1 was great", (*added.SeasonsComments)["1"].Comment)
	require.Equal(t, "season 2 was better", (*added.SeasonsComments)["2"].Comment)

	got, err := s.GetCommentById(ctx, added.Id, userId)
	require.NoError(t, err)
	require.Nil(t, got.Comment)
	require.NotNil(t, got.SeasonsComments)
	require.Len(t, *got.SeasonsComments, 2)
	require.Equal(t, (*added.SeasonsComments)["1"].Comment, (*got.SeasonsComments)["1"].Comment)
	require.Equal(t, (*added.SeasonsComments)["2"].Comment, (*got.SeasonsComments)["2"].Comment)
	require.WithinDuration(t, (*added.SeasonsComments)["1"].AddedAt, (*got.SeasonsComments)["1"].AddedAt, time.Second)
}

func TestStore_GetUserCommentByTitleId(t *testing.T) {
	t.Run("round trip", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupId := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()
		added, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupId, "nice"))
		require.NoError(t, err)

		got, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupId)
		require.NoError(t, err)
		require.Equal(t, added, got)
	})

	t.Run("resolves the requested group's row when the user commented twice", func(t *testing.T) {
		// The underlying query is a sqlc :one, which compiles to QueryRow and
		// silently discards every row after the first. Without the group_id
		// predicate this lookup returns an arbitrary one of the two rows.
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		inA, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "for group A"))
		require.NoError(t, err)
		inB, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "for group B"))
		require.NoError(t, err)

		gotA, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupA)
		require.NoError(t, err)
		require.Equal(t, inA.Id, gotA.Id, "the (user, title) lookup must resolve group A's row, not group B's")
		require.Equal(t, groupA, gotA.GroupId)
		require.Equal(t, "for group A", *gotA.Comment)

		gotB, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
		require.NoError(t, err)
		require.Equal(t, inB.Id, gotB.Id, "the (user, title) lookup must resolve group B's row, not group A's")
		require.Equal(t, groupB, gotB.GroupId)
		require.Equal(t, "for group B", *gotB.Comment)
	})

	t.Run("a comment in another group is not visible to this group", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		_, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "only in A"))
		require.NoError(t, err)

		_, err = s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
		require.ErrorIs(t, err, store.ErrRecordNotFound, "group B must not see the comment written in group A")
	})

	t.Run("not found", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		_, err := s.GetUserCommentByTitleId(ctx, "missing-title", "missing-user", "missing-group")
		require.ErrorIs(t, err, store.ErrRecordNotFound)
	})
}

func TestStore_AddComment_SameTitleInTwoGroups(t *testing.T) {
	// A comment is a (user, title, group) fact: the same user may say
	// different things about the same title in two groups, and both rows stand
	// on their own.
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupA := addTestGroup(t, s)
	groupB := addTestGroup(t, s)
	titleId := "tt-" + uuid.NewString()
	userId := "user-" + uuid.NewString()

	inA, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "loved it"))
	require.NoError(t, err)
	inB, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "overrated"))
	require.NoError(t, err, "commenting on a title already commented on in another group must be allowed")

	require.NotEqual(t, inA.Id, inB.Id, "the two comments must be distinct rows")
	require.Equal(t, groupA, inA.GroupId)
	require.Equal(t, groupB, inB.GroupId)

	// Each group's read path sees exactly its own comment.
	commentsA, err := s.GetCommentsByTitleId(ctx, titleId, groupA)
	require.NoError(t, err)
	require.Len(t, commentsA, 1, "group A must see only its own comment on the title")
	require.Equal(t, inA.Id, commentsA[0].Id)
	require.Equal(t, "loved it", *commentsA[0].Comment)

	commentsB, err := s.GetCommentsByTitleId(ctx, titleId, groupB)
	require.NoError(t, err)
	require.Len(t, commentsB, 1, "group B must see only its own comment on the title")
	require.Equal(t, inB.Id, commentsB[0].Id)
	require.Equal(t, "overrated", *commentsB[0].Comment)

	// Updating one group's comment leaves the other untouched.
	revised := "second thoughts"
	_, err = s.UpdateComment(ctx, models.Comment{Id: inB.Id, Comment: &revised}, userId)
	require.NoError(t, err)

	rereadA, err := s.GetCommentById(ctx, inA.Id, userId)
	require.NoError(t, err)
	require.Equal(t, "loved it", *rereadA.Comment, "updating group B's comment must not touch group A's")
	rereadB, err := s.GetCommentById(ctx, inB.Id, userId)
	require.NoError(t, err)
	require.Equal(t, "second thoughts", *rereadB.Comment)
}

