func TestStore_UpdateComment_ReplacesSeasonSet(t *testing.T) {
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupId := addTestGroup(t, s)
	titleId := "tt-" + uuid.NewString()
	userId := "user-" + uuid.NewString()
	added, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, userId, groupId, map[string]string{
		"1": "first", "2": "second",
	}))
	require.NoError(t, err)
	require.Len(t, *added.SeasonsComments, 2)

	now := time.Now().UTC().Truncate(time.Second)
	newSeasons := models.SeasonsComments{
		"2": {Comment: "second-updated", AddedAt: (*added.SeasonsComments)["2"].AddedAt, UpdatedAt: now},
		"3": {Comment: "third", AddedAt: now, UpdatedAt: now},
	}
	update := models.Comment{
		Id:              added.Id,
		SeasonsComments: &newSeasons,
	}

	updated, err := s.UpdateComment(ctx, update, userId)
	require.NoError(t, err)
	require.Equal(t, groupId, updated.GroupId, "an update must not move the comment out of its group")
	require.NotNil(t, updated.SeasonsComments)
	require.Len(t, *updated.SeasonsComments, 2)
	require.NotContains(t, *updated.SeasonsComments, "1", "season 1 must have been dropped by the whole-map replace")
	require.Contains(t, *updated.SeasonsComments, "2")
	require.Contains(t, *updated.SeasonsComments, "3")
	require.Equal(t, "second-updated", (*updated.SeasonsComments)["2"].Comment)
	require.Equal(t, "third", (*updated.SeasonsComments)["3"].Comment)

	// Re-read from scratch must reflect exactly the new map, proving the
	// delete+reinsert was actually persisted (not just returned in-memory).
	reread, err := s.GetCommentById(ctx, added.Id, userId)
	require.NoError(t, err)
	require.NotNil(t, reread.SeasonsComments)
	require.Len(t, *reread.SeasonsComments, 2)
	require.NotContains(t, *reread.SeasonsComments, "1")
	require.Equal(t, "second-updated", (*reread.SeasonsComments)["2"].Comment)
	require.Equal(t, "third", (*reread.SeasonsComments)["3"].Comment)
}

func TestStore_SeriesComment_PerSeasonPathsResolveTheRightGroup(t *testing.T) {
	// The TV-series add/update flow looks its row up by (user, title, group)
	// and then replaces that row's whole season map. With two groups holding a
	// comment on the same series, each side must move independently.
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupA := addTestGroup(t, s)
	groupB := addTestGroup(t, s)
	titleId := "tt-series-" + uuid.NewString()
	userId := "user-" + uuid.NewString()

	inA, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, userId, groupA, map[string]string{"1": "A season 1"}))
	require.NoError(t, err)
	inB, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, userId, groupB, map[string]string{
		"1": "B season 1", "2": "B season 2",
	}))
	require.NoError(t, err)

	// The add path's "does this user already have a comment here?" lookup must
	// return the group's own row, with the group's own seasons.
	lookupA, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupA)
	require.NoError(t, err)
	require.Equal(t, inA.Id, lookupA.Id)
	require.NotNil(t, lookupA.SeasonsComments)
	require.Len(t, *lookupA.SeasonsComments, 1, "group A's row must carry only group A's seasons")
	require.Equal(t, "A season 1", (*lookupA.SeasonsComments)["1"].Comment)

	lookupB, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
	require.NoError(t, err)
	require.Equal(t, inB.Id, lookupB.Id)
	require.Len(t, *lookupB.SeasonsComments, 2, "group B's row must carry only group B's seasons")

	// Add a season to group B's comment, the way the series update path does:
	// take the row it just resolved, extend its map, write it back.
	now := time.Now().UTC().Truncate(time.Second)
	seasonsB := *lookupB.SeasonsComments
	seasonsB["3"] = models.SeasonCommentItem{Comment: "B season 3", AddedAt: now, UpdatedAt: now}
	_, err = s.UpdateComment(ctx, models.Comment{Id: lookupB.Id, SeasonsComments: &seasonsB}, userId)
	require.NoError(t, err)

	rereadB, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
	require.NoError(t, err)
	require.Len(t, *rereadB.SeasonsComments, 3)
	require.Equal(t, "B season 3", (*rereadB.SeasonsComments)["3"].Comment)

	rereadA, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupA)
	require.NoError(t, err)
	require.Equal(t, inA.Id, rereadA.Id)
	require.Len(t, *rereadA.SeasonsComments, 1, "group A's seasons must be untouched by an update in group B")
	require.Equal(t, "A season 1", (*rereadA.SeasonsComments)["1"].Comment)
}

