func TestStore_GetCommentsByTitleId_FiltersByGroup(t *testing.T) {
	// Comments are read through the group they belong to: the row carries its
	// group, so this filters on group_id rather than on the group's member
	// list. A comment written in another group must never appear here, even
	// when its author is also a member of the requesting group.
	resetDB(t)
	s := newTestStore(t)
	ctx := context.Background()

	groupId := addTestGroup(t, s)
	otherGroupId := addTestGroup(t, s)
	titleId := "tt-" + uuid.NewString()
	otherTitleId := "tt-other-" + uuid.NewString()

	c1, err := s.AddComment(ctx, newTestMovieComment(t, titleId, "user-1", groupId, "from user 1"))
	require.NoError(t, err)
	c2, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, "user-2", groupId, map[string]string{"1": "s1"}))
	require.NoError(t, err)
	// user-1 comments on the same title in another group: same author, same
	// title, different fact — it must be excluded from this group's read.
	excluded, err := s.AddComment(ctx, newTestMovieComment(t, titleId, "user-1", otherGroupId, "excluded, other group"))
	require.NoError(t, err)
	// A comment by a user this group never sees, in the other group.
	_, err = s.AddComment(ctx, newTestMovieComment(t, titleId, "user-3", otherGroupId, "excluded, other user"))
	require.NoError(t, err)
	// Same group, different title.
	_, err = s.AddComment(ctx, newTestMovieComment(t, otherTitleId, "user-1", groupId, "different title"))
	require.NoError(t, err)

	got, err := s.GetCommentsByTitleId(ctx, titleId, groupId)
	require.NoError(t, err)
	require.Len(t, got, 2, "only the requested group's comments on the title may be returned")

	byId := map[string]models.Comment{}
	for _, c := range got {
		byId[c.Id] = c
		require.Equal(t, groupId, c.GroupId, "every returned comment must belong to the requested group")
	}
	require.Contains(t, byId, c1.Id)
	require.Contains(t, byId, c2.Id)
	require.NotContains(t, byId, excluded.Id, "a comment from another group leaked into this group's read")
	require.Nil(t, byId[c1.Id].SeasonsComments)
	require.NotNil(t, byId[c2.Id].SeasonsComments)
	require.Len(t, *byId[c2.Id].SeasonsComments, 1)

	// The mirror image: the other group sees only its own two.
	other, err := s.GetCommentsByTitleId(ctx, titleId, otherGroupId)
	require.NoError(t, err)
	require.Len(t, other, 2, "the other group must see exactly its own two comments")
	for _, c := range other {
		require.Equal(t, otherGroupId, c.GroupId)
	}

	empty, err := s.GetCommentsByTitleId(ctx, "no-such-title", groupId)
	require.NoError(t, err)
	require.Equal(t, []models.Comment{}, empty)
}

func TestStore_DeleteComment(t *testing.T) {
	t.Run("deletes comment and cascades its seasons", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupId := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()
		added, err := s.AddComment(ctx, newTestSeriesComment(t, titleId, userId, groupId, map[string]string{"1": "s1"}))
		require.NoError(t, err)

		count, err := s.DeleteComment(ctx, added.Id, userId, groupId)
		require.NoError(t, err)
		require.EqualValues(t, 1, count)

		_, err = s.GetCommentById(ctx, added.Id, userId)
		require.ErrorIs(t, err, store.ErrRecordNotFound)

		var seasonCount int
		err = s.pool.QueryRow(ctx, `SELECT count(*) FROM comment_seasons WHERE comment_id = $1`, added.Id).Scan(&seasonCount)
		require.NoError(t, err)
		require.Zero(t, seasonCount, "comment_seasons rows must cascade-delete with their parent comment")
	})

	t.Run("deletes only the targeted group's comment", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		inA, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "in A"))
		require.NoError(t, err)
		inB, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "in B"))
		require.NoError(t, err)

		count, err := s.DeleteComment(ctx, inA.Id, userId, groupA)
		require.NoError(t, err)
		require.EqualValues(t, 1, count)

		_, err = s.GetUserCommentByTitleId(ctx, titleId, userId, groupA)
		require.ErrorIs(t, err, store.ErrRecordNotFound)

		survivor, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
		require.NoError(t, err, "deleting group A's comment must leave group B's alone")
		require.Equal(t, inB.Id, survivor.Id)
	})

	t.Run("a comment id from another group deletes nothing", func(t *testing.T) {
		// group_id is part of the key the delete matches on, so an id naming the
		// same user's comment in a different group is simply not there.
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		inA, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "in A"))
		require.NoError(t, err)
		inB, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "in B"))
		require.NoError(t, err)

		count, err := s.DeleteComment(ctx, inB.Id, userId, groupA)
		require.NoError(t, err)
		require.Zero(t, count, "group B's comment id must not be deletable through group A")

		stillA, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupA)
		require.NoError(t, err, "group A's comment must survive a delete addressed with group B's id")
		require.Equal(t, inA.Id, stillA.Id)

		stillB, err := s.GetUserCommentByTitleId(ctx, titleId, userId, groupB)
		require.NoError(t, err, "group B's comment must survive a delete scoped to group A")
		require.Equal(t, inB.Id, stillB.Id)
	})

	t.Run("not found reports a zero count with no error", func(t *testing.T) {
		// A zero-affected delete is not mapped to
		// store.ErrRecordNotFound; it just returns the (zero) count.
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		count, err := s.DeleteComment(ctx, "missing-comment", "missing-user", "missing-group")
		require.NoError(t, err)
		require.Zero(t, count)
	})
}

func TestAddComment_DuplicateUserTitle(t *testing.T) {
	t.Run("same user, title and group is a duplicate", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupId := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		added, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupId, "first comment"))
		require.NoError(t, err)
		require.NotEmpty(t, added.Id)

		_, err = s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupId, "second comment"))
		require.ErrorIs(t, err, store.ErrDuplicatedRecord, "a second comment on the same title in the same group must be refused")
	})

	t.Run("same user and title in a different group is not a duplicate", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-" + uuid.NewString()
		userId := "user-" + uuid.NewString()

		_, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "first comment"))
		require.NoError(t, err)

		second, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "second comment"))
		require.NoError(t, err, "the same (user, title) in another group is a different fact and must be accepted")
		require.Equal(t, groupB, second.GroupId)
	})
}

// TestStore_Comments_CascadeOnGroupDelete is the comments half of the
// ON DELETE CASCADE contract asserted in ratings_test.go.
func TestStore_Comments_CascadeOnGroupDelete(t *testing.T) {
	t.Run("hard-deleting a group removes its comments", func(t *testing.T) {
		resetDB(t)
		s := newTestStore(t)
		ctx := context.Background()

		groupA := addTestGroup(t, s)
		groupB := addTestGroup(t, s)
		titleId := "tt-cascade-" + uuid.NewString()
		userId := "user-cascade-" + uuid.NewString()

		_, err := s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupA, "in the doomed group"))
		require.NoError(t, err, "failed to seed the comment in the group being deleted")
		_, err = s.AddComment(ctx, newTestMovieComment(t, titleId, userId, groupB, "in the surviving group"))
		require.NoError(t, err, "failed to seed the comment in the surviving group")

		_, err = newTestPool(t).Exec(ctx, `DELETE FROM groups WHERE id = $1`, groupA)
		require.NoError(t, err, "hard-deleting a group must succeed, not be blocked by the comments foreign key")

		gone, err := s.GetCommentsByTitleId(ctx, titleId, groupA)
		require.NoError(t, err)
		require.Empty(t, gone, "the deleted group's comments must be gone")

		kept, err := s.GetCommentsByTitleId(ctx, titleId, groupB)
		require.NoError(t, err)
		require.Len(t, kept, 1, "the other group's comment must survive the cascade")
	})
}
